 IF NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid='public.learning_results'::regclass AND attname='user_id' AND attnum>0 AND NOT attisdropped AND (atttypid='uuid'::regtype) AND attnotnull=true) THEN RAISE EXCEPTION 'Column drift learning_results.user_id'; END IF;
