 IF NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid='public.learning_summaries'::regclass AND attname='status' AND attnum>0 AND NOT attisdropped AND (atttypid='varchar'::regtype OR atttypid='text'::regtype) AND attnotnull=true) THEN RAISE EXCEPTION 'Column drift learning_summaries.status'; END IF;
