 IF NOT EXISTS(SELECT 1 FROM pg_constraint c JOIN pg_attribute a ON a.attrelid=c.conrelid AND a.attname='id' WHERE c.conrelid='public.learning_summaries'::regclass AND c.contype='p' AND c.conkey=ARRAY[a.attnum]::smallint[]) THEN RAISE EXCEPTION 'Missing ID primary key learning_summaries'; END IF;
