 SELECT i.indrelid,i.indisunique,i.indisvalid,i.indisready,i.indpred IS NOT NULL AS partial, ARRAY(SELECT a.attname::text FROM unnest(i.indkey) WITH ORDINALITY k(attnum,ordinal) JOIN pg_attribute a ON a.attrelid=i.indrelid AND a.attnum=k.attnum ORDER BY k.ordinal) AS actual_columns INTO info FROM pg_index i WHERE i.indexrelid=to_regclass('public.uq_learning_results_source');
 IF NOT FOUND OR info.indrelid<>'public.learning_results'::regclass OR info.indisunique<>true OR NOT info.indisvalid OR NOT info.indisready OR info.actual_columns<>ARRAY['source_id','source_type'] OR info.partial<>false THEN RAISE EXCEPTION 'Index drift uq_learning_results_source'; END IF;
 SELECT i.indrelid,i.indisunique,i.indisvalid,i.indisready,i.indpred IS NOT NULL AS partial, ARRAY(SELECT a.attname::text FROM unnest(i.indkey) WITH ORDINALITY k(attnum,ordinal) JOIN pg_attribute a ON a.attrelid=i.indrelid AND a.attnum=k.attnum ORDER BY k.ordinal) AS actual_columns INTO info FROM pg_index i WHERE i.indexrelid=to_regclass('public.uq_learning_results_user_target_attempt');
