 IF NOT FOUND OR info.indrelid<>'public.learning_summaries'::regclass OR info.indisunique<>false OR NOT info.indisvalid OR NOT info.indisready OR info.actual_columns<>ARRAY['user_id'] OR info.partial<>false THEN RAISE EXCEPTION 'Index drift ix_learning_summaries_user_id'; END IF;
