$body$;
-- Screen14/16 additions: fail on missing migrations; never repair schema from application code.
DO $screen14_16$
DECLARE name TEXT;
BEGIN
 FOREACH name IN ARRAY ARRAY['study_question_facts','practice_exp_policy_events',
   'result_projection_adjustments','leaderboard_public_profiles','screen14_exam_facts',
   'result_projection_exclusions','source_exam_scales','practice_exp_source_state',
   'ix_study_question_period','ix_projection_adjustment_source','ix_exp_policy_latest',
   'ix_exam_analytics_scope','ix_exam_exp_scope'] LOOP
  IF to_regclass('public.'||name) IS NULL THEN RAISE EXCEPTION 'Missing Screen14/16 relation %',name; END IF;
 END LOOP;
 IF to_regprocedure('public.dts_exp_credits(text,timestamptz,timestamptz)') IS NULL THEN
  RAISE EXCEPTION 'Missing EXP credit function'; END IF;
 IF (SELECT COUNT(*) FROM pg_trigger WHERE NOT tgisinternal AND tgenabled IN ('O','A')
    AND tgname IN ('trg_study_question_immutable','trg_projection_adjustment_immutable','trg_exp_policy_immutable')
    AND tgfoid='public.dts_preserve_projection_fact()'::regprocedure)<>3 THEN
  RAISE EXCEPTION 'Missing append-only projection guards'; END IF;
END;
$screen14_16$;
DO $body$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_index WHERE indexrelid='public.uq_learning_results_source'::regclass AND indisunique AND indisvalid) THEN
    RAISE EXCEPTION 'Missing unique source guard'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid='public.learning_results'::regclass AND attname='activity_type' AND NOT attisdropped)
    OR NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid='public.learning_results'::regclass AND attname='result_available' AND NOT attisdropped)
    OR to_regclass('public.ix_history_user_completed') IS NULL OR to_regclass('public.ix_history_exam_filters') IS NULL THEN
    RAISE EXCEPTION 'Missing Screen13 history schema'; END IF;
 IF pg_get_expr((SELECT indpred FROM pg_index WHERE indexrelid='public.uq_learning_results_user_target_attempt'::regclass),
    'public.learning_results'::regclass) NOT LIKE '%target_type%<>%EXAM%' THEN
    RAISE EXCEPTION 'Attempt uniqueness must exclude EXAM'; END IF;
END;
$body$;
